changeSet.sql:
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

CREATE TABLE IF NOT EXISTS "user".user_package (
    id          UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL,
    package_id  UUID,
    user_id     UUID NOT NULL,
    exp_date    TIMESTAMP,
    deleted     BOOLEAN DEFAULT FALSE,
    created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS user_idx_user_package_user ON "user".user_package(user_id);

CREATE TABLE IF NOT EXISTS "user".user_package_template (
    id              UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL,
    user_package_id UUID NOT NULL REFERENCES "user".user_package(id) ON DELETE CASCADE,
    template_id     UUID NOT NULL,
    limit_count     INTEGER NOT NULL DEFAULT 0,
    usage_count     INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS user_idx_upt_pkg ON "user".user_package_template(user_package_id);
CREATE INDEX IF NOT EXISTS user_idx_upt_template ON "user".user_package_template(template_id);
